read_numeric="""(async()=>{await document.fonts.ready;await new Promise(r=>requestAnimationFrame(()=>requestAnimationFrame(r)));const items=[...document.querySelectorAll('.mg-stats-card-item__value')];return items.map(n=>{const css=getComputedStyle(n),features=css.fontVariantNumeric,children=[];for(const numeric of [features,'normal']){const el=document.createElement('span');el.textContent=n.textContent;for(const name of css)el.style.setProperty(name,css.getPropertyValue(name));el.style.position='fixed';el.style.left='-9000px';el.style.top='0';el.style.width='auto';el.style.height='auto';el.style.fontVariantNumeric=numeric;document.body.appendChild(el);const range=document.createRange();range.selectNodeContents(el);const r=range.getBoundingClientRect();children.push({fontVariantNumeric:numeric,characters:el.textContent,width:r.width,height:r.height,fontFamily:getComputedStyle(el).fontFamily,fontSize:getComputedStyle(el).fontSize,fontWeight:getComputedStyle(el).fontWeight});el.remove();}return {characters:n.textContent,sourceFeatures:features,sourceAndNormalMeasurements:children};});})()"""
allcases=[]
for mode,theme in themes.items():
 for width in [390,1164]:
  cli('set','viewport',str(width),'1000')
  for preset in ['default','with-icons','compact','highlighted','negative','linked','mixed-content']:
   url='http://localhost:6121/iframe.html?'+urllib.parse.urlencode({'id':'components-cards-stats-card--'+preset,'viewMode':'story','globals':'theme:'+theme+';locale:english'})
   cli('open',url);cli('wait','--fn','!!document.querySelector(".mg-stats-card-item__value")')
   allcases.append({'mode':mode,'viewport':width,'preset':preset,'items':cli('eval',read_numeric)})
   (OUT/'numeric-feature-browser-readout.json').write_text(json.dumps(allcases,indent=2)+'\n')
  print(mode,width,len(allcases),flush=True)
